import sys, json

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(arr):
    if not arr: return None
    nodes = [TreeNode(v) if v is not None else None for v in arr]
    it = iter(nodes)
    try:
        root = next(it)
    except StopIteration:
        return None
    queue = [root]
    for node in queue:
        if node:
            try:
                node.left = next(it)
                queue.append(node.left)
                node.right = next(it)
                queue.append(node.right)
            except StopIteration:
                break
    return root

def get_level_order(root):
    if not root: return []
    res = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node:
            res.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
        else:
            res.append(None)
    while res and res[-1] is None: res.pop()
    return res

def solve(root):
    curr = root
    while curr:
        if curr.left:
            last = curr.left
            while last.right:
                last = last.right
            last.right = curr.right
            curr.right = curr.left
            curr.left = None
        curr = curr.right
    return root

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        arr = json.loads(line)
        root = build_tree(arr)
        root = solve(root)
        print(json.dumps(get_level_order(root)).replace("null", "null"))
    else:
        print("[]")

